 dict(kind="content", icon="📘", head="अमेरिका का संविधान (1787)",
      points=["फ़िलाडेल्फ़िया सम्मेलन में बना, 1789 से लागू", "दुनिया का पहला लिखित संविधान (आधुनिक राष्ट्र का)", "संघीय व्यवस्था: केंद्र + राज्य सरकारें", "शक्ति विभाजन: कार्यपालिका (राष्ट्रपति), विधायिका (कांग्रेस), न्यायपालिका"],
      say="आज़ादी के बाद, नए देश को चलाने के लिए नियम चाहिए थे। सत्रह सौ सत्तासी में, फ़िलाडेल्फ़िया में, अमेरिका का संविधान बना, जो सत्रह सौ नवासी से लागू हुआ। इसे किसी आधुनिक राष्ट्र का पहला लिखित संविधान माना जाता है। इसमें संघीय व्यवस्था रखी गई, यानी एक केंद्र सरकार, और राज्यों की अपनी सरकारें। और शक्ति को तीन हिस्सों में बाँटा, क़ानून लागू करने वाली कार्यपालिका, यानी राष्ट्रपति। क़ानून बनाने वाली विधायिका, यानी कांग्रेस। और न्याय करने वाली न्यायपालिका। ताकि कोई एक हिस्सा तानाशाह न बन सके।"),

 dict(kind="content", icon="🇺🇸", head="पहले राष्ट्रपति: जॉर्ज वाशिंगटन",
      points=["1789 में पहले राष्ट्रपति बने", "दो कार्यकाल के बाद ख़ुद पद छोड़ा — सत्ता का मोह नहीं", "'अमेरिका के राष्ट्रपिता' कहलाते हैं", "1791: अधिकार-पत्र (Bill of Rights) — बोलने, धर्म, प्रेस की आज़ादी"],
      say="जॉर्ज वाशिंगटन, सत्रह सौ नवासी में, अमेरिका के पहले राष्ट्रपति बने। दो बार राष्ट्रपति रहने के बाद, उन्होंने ख़ुद पद छोड़ दिया, जबकि लोग चाहते थे कि वो आगे भी रहें। उन्होंने दिखाया कि लोकतंत्र में कोई हमेशा के लिए सत्ता में नहीं रहता। इसीलिए उन्हें अमेरिका का राष्ट्रपिता कहते हैं। सत्रह सौ इक्यानवे में संविधान में अधिकार-पत्र जोड़ा गया, जिसमें बोलने, धर्म मानने और अख़बार निकालने की आज़ादी जैसे अधिकार दिए गए।"),

