 dict(kind="content", icon="☕", head="कहानी का अंत",
      points=["रमेश: तो चाय से एक देश आज़ाद हुआ!", "मास्टर जी: चाय नहीं, हक़ की आवाज़ से", "'जो कर देता है, उसे बोलने का हक़'", "दादाजी: आज भी यही लोकतंत्र की जान है"],
      say="कहानी सुनकर रमेश बोला, मास्टर जी, मतलब चाय की वजह से एक पूरा देश आज़ाद हो गया! मास्टर जी हँसे, चाय की वजह से नहीं, अपने हक़ की आवाज़ उठाने से। जो कर देता है, उसे ये तय करने में भी हिस्सा मिलना चाहिए कि कर कैसे और कितना लगे। दादाजी ने चाय का गिलास बढ़ाते हुए कहा, आज भी लोकतंत्र की जान यही है, जनता की आवाज़।"),

 dict(kind="list", icon="📝", head="पूरे पाठ का सार",
      points=["13 अंग्रेज़ उपनिवेश · वाणिज्यवाद, नेविगेशन क़ानून", "सप्तवर्षीय युद्ध के बाद नए कर: शुगर, स्टांप, टाउनशेंड, टी एक्ट", "'प्रतिनिधित्व नहीं, तो कर नहीं' · बोस्टन हत्याकांड (1770), बोस्टन टी पार्टी (1773)", "लेक्सिंगटन (1775) · स्वतंत्रता की घोषणा 4 जुलाई 1776 (जेफ़र्सन) · सारातोगा (1777) · यॉर्कटाउन (1781) · पेरिस संधि (1783)", "संविधान 1787 · वाशिंगटन पहले राष्ट्रपति (1789)"],
      say="तो बच्चों, सार। एक, अटलांटिक तट पर तेरह अंग्रेज़ उपनिवेश, और इंग्लैंड की वाणिज्यवादी नीति। दो, सप्तवर्षीय युद्ध के बाद नए-नए कर। तीन, प्रतिनिधित्व नहीं तो कर नहीं का नारा, बोस्टन हत्याकांड और बोस्टन टी पार्टी। चार, सत्रह सौ पचहत्तर में युद्ध, चार जुलाई सत्रह सौ छिहत्तर को स्वतंत्रता की घोषणा, सारातोगा, यॉर्कटाउन, और सत्रह सौ तिरासी में पेरिस की संधि। पाँच, संविधान, और वाशिंगटन पहले राष्ट्रपति।"),

